fn findMax(a: &[i32], n: usize) -> usize {
    // We assume n > 0 and n <= a.len()
    let mut max_index = 0;
    for i in 1..n {
        if a[i] > a[max_index] {
            max_index = i;
        }
    }
    max_index
}

